<script lang="ts">
 import {player,prev,next,togglePause,seek,setVolume,fmtTime} from '$lib/player.svelte';
 import {compact} from '$lib/compact.svelte';
 const progress=$derived(player.status.duration>0?Math.max(0,Math.min(1,player.status.position/player.status.duration)):0);
 const playing=$derived(player.status.index!==null&&!player.status.paused);
</script>
<div class="cabinet" data-tauri-drag-region>
 <header data-tauri-drag-region>Análogo · Estéreo</header>
 <div class="info" data-tauri-drag-region><h1 data-tauri-drag-region title={player.track?.title}>{player.track?.title||'Sintoniza una canción'}</h1><p data-tauri-drag-region>{player.track?.artist||'Sin artista'}</p></div>
 <div class="dial"><div class="marks" aria-hidden="true">0　　20　　40　　60　　80　　100</div><span class="needle" style:left={`${5+progress*90}%`}></span><span class="dial-label" aria-hidden="true">RECORRIDO · %</span><input aria-label="Posición de reproducción" type="range" min="0" max={player.status.duration||1} step="0.1" value={player.status.position} disabled={!player.status.duration} oninput={e=>seek(+e.currentTarget.value)}/></div>
 <div class="readout" data-tauri-drag-region><time data-tauri-drag-region>{fmtTime(player.status.position)}</time><span data-tauri-drag-region> / {fmtTime(player.status.duration)}</span><span class="lamp" class:lit={playing} aria-hidden="true"></span><span data-tauri-drag-region>{playing?'EN EL AIRE':'EN ESPERA'}</span></div>
 <div class="controls"><button class="knob" aria-label="Canción anterior" onclick={prev}>|◀</button><button class="knob play" aria-label={playing?'Pausar':'Reproducir'} onclick={togglePause}>{playing?'Ⅱ':'▶'}</button><button class="knob" aria-label="Canción siguiente" onclick={next}>▶|</button><label class="volume"><span>Volumen</span><input aria-label="Volumen" type="range" min="0" max="100" value={player.status.volume} style:--angle={`${-135+player.status.volume*2.7}deg`} oninput={e=>setVolume(+e.currentTarget.value)}/></label><div class="toggles"><button aria-label="Ecualizador" aria-pressed={compact.eq} onclick={()=>compact.eq=!compact.eq}>EQ</button><button aria-label="Lista de reproducción" aria-pressed={compact.playlist} onclick={()=>compact.playlist=!compact.playlist}>PL</button></div></div>
</div>
