ex-direction:column;align-items:center;gap:2px;font-size:9px}.volume input{appearance:none;width:39px;height:39px;margin:0;border:3px solid #17120d;border-radius:50%;background:radial-gradient(circle,#504334,#211913);cursor:ew-resize;transform:rotate(var(--angle));box-shadow:0 2px 4px #000}.volume input::-webkit-slider-runnable-track{height:100%;background:linear-gradient(#ffedc7,#ffedc7) center top/2px 10px no-repeat}.volume input::-webkit-slider-thumb{appearance:none;width:1px;height:1px;opacity:0}.volume input::-moz-range-track{height:100%;background:linear-gradient(#ffedc7,#ffedc7) center top/2px 10px no-repeat}.volume input::-moz-range-thumb{opacity:0}.toggles{display:flex;flex-direction:column;gap:5px}.toggles button{border:1px solid #947042;border-radius:3px;background:#21150f;color:#ffedc7;font:10px Georgia,serif;padding:4px 7px;cursor:pointer}.toggles button[aria-pressed=true]{background:#f4af4f;color:#21150f}button:hover{filter:brightness(1.25)}button:focus-visible,input:focus-visible{outline:2px solid #ffedc7;outline-offset:2px}
